"use client";

import { cva } from "class-variance-authority";
import type { VariantProps } from "class-variance-authority";
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from "react";
import type { ComponentProps, CSSProperties, Ref, RefObject } from "react";
import { useEffectEvent } from "./audio-meters-use-effect-event";

import { ClipIndicator } from "./audio-meters-clip-indicator";
import type { ClipIndicatorProps } from "./audio-meters-clip-indicator";
import { DbReadout, readChannel } from "./audio-meters-db-readout";
import type { DbReadoutProps } from "./audio-meters-db-readout";
import { DbScale } from "./audio-meters-db-scale";
import type { DbScaleProps } from "./audio-meters-db-scale";
import { useAudioConfig } from "./audio-meters-use-audio-config";
import type { AudioSize } from "./audio-meters-use-audio-config";
import { useFrameSource } from "./audio-meters-use-frame-source";
import { useReducedMotion } from "./audio-meters-use-reduced-motion";
import { useVisibility } from "./audio-meters-use-visibility";
import { createBallistics, resolveBallistics } from "./audio-meters-ballistics";
import type { Ballistics, BallisticsInput } from "./audio-meters-ballistics";
import {
  DEFAULT_MAX_DB,
  DEFAULT_MIN_DB,
  formatDb,
  SILENCE_DB,
} from "./audio-meters-decibels";
import { createFrameTask, createPainterClock } from "./audio-meters-frame-loop";
import { createFrameEmitter } from "./audio-meters-frame-source";
import { resolveTaper } from "./audio-meters-taper";
import type { TaperInput } from "./audio-meters-taper";
import type {
  ChannelLevel,
  FrameSource,
  MeterFrame,
  MeterZone,
  Orientation,
  Taper,
} from "./audio-meters-types";
import {
  CLIP_HOLD_MS,
  CLIP_THRESHOLD_DB,
  DEFAULT_ZONES,
  zoneForDb,
} from "./audio-meters-zones";
import { cn } from "@/lib/utils";

const ARIA_INTERVAL_MS = 250;
const REDUCED_MOTION_INTERVAL_MS = 250;
const DEFAULT_SEGMENTS = 24;
const POSITION_EPSILON = 0.0005;
/**
 * A meter this close to its input has nothing visible left to animate (about
 * 0.06 dB on the default range, under a pixel on any meter), so it sleeps.
 */
const SETTLE_EPSILON = 0.001;

export type LevelMeterVariant = "solid" | "segmented" | "gradient";

export interface LevelMeterActions {
  /** Paint a frame directly, for callers that own their own frame loop. */
  paint: (frame: MeterFrame) => void;
  /** Drop the level and the peak hold to silence. */
  reset: () => void;
}

export interface LevelMeterContextValue {
  orientation: Orientation;
  variant: LevelMeterVariant;
  minDb: number;
  maxDb: number;
  taper: Taper;
  zones: MeterZone[];
  /** Tracks the meter shows: declared, seen in the frames, or `channelCount`. */
  channelCount: number;
  frames: FrameSource<MeterFrame>;
  /** The declarative levels, when the meter has values instead of a source. */
  declared: MeterFrame | null;
  registerChannel: (index: number, element: HTMLElement | null) => void;
}

const LevelMeterContext = createContext<LevelMeterContextValue | null>(null);

/** The surrounding meter's range, scale and frames, for parts built on it. */
export const useLevelMeter = (part: string) => {
  const context = useContext(LevelMeterContext);
  if (!context) {
    throw new Error(`${part} must be used inside LevelMeter.`);
  }
  return context;
};

/**
 * Zones in rising order, as a new array. An insertion rather than the ES2023
 * sorted-copy method, which projects compiling against ES2022 lack; a meter
 * has a handful of zones.
 */
const byFromDb = (zones: MeterZone[]): MeterZone[] => {
  const sorted: MeterZone[] = [];
  for (const zone of zones) {
    const index = sorted.findIndex((other) => other.fromDb > zone.fromDb);
    if (index === -1) {
      sorted.push(zone);
    } else {
      sorted.splice(index, 0, zone);
    }
  }
  return sorted;
};

const buildZoneFill = (
  zones: MeterZone[],
  taper: Taper,
  orientation: Orientation,
  variant: LevelMeterVariant
) => {
  const direction = orientation === "horizontal" ? "to right" : "to top";
  const sorted = byFromDb(zones);
  // Rounded so the server and the browser print the same stops.
  const starts = sorted.map((zone) =>
    Number((taper.toPosition(zone.fromDb) * 100).toFixed(3))
  );

  if (variant === "gradient") {
    const stops = sorted.map(
      (zone, index) => `var(--meter-${zone.zone}) ${starts[index] ?? 0}%`
    );
    const last = sorted.at(-1);
    return `linear-gradient(${direction}, ${stops.join(", ")}, var(--meter-${last?.zone ?? "ok"}) 100%)`;
  }

  const stops = sorted.map((zone, index) => {
    const start = starts[index] ?? 0;
    const end = starts[index + 1] ?? 100;
    return `var(--meter-${zone.zone}) ${start}% ${end}%`;
  });
  return `linear-gradient(${direction}, ${stops.join(", ")})`;
};

const buildSegmentMask = (orientation: Orientation, segments: number) => {
  const direction = orientation === "horizontal" ? "to right" : "to top";
  const size = `calc(100% / ${segments})`;
  return `repeating-linear-gradient(${direction}, black 0 calc(${size} - 2px), transparent calc(${size} - 2px) ${size})`;
};

const serializeLevels = (
  channels: ChannelLevel[] | undefined,
  peakDb: number | undefined,
  rmsDb: number | undefined
): string => {
  if (channels) {
    return channels.map((level) => `${level.peakDb}:${level.rmsDb}`).join("|");
  }
  if (peakDb === undefined && rmsDb === undefined) {
    return "";
  }
  return `${peakDb ?? SILENCE_DB}:${rmsDb}`;
};

const parseNumber = (text: string | undefined): number | undefined => {
  const value = Number(text);
  return Number.isNaN(value) ? undefined : value;
};

const parseLevels = (key: string): MeterFrame | null => {
  if (key === "") {
    return null;
  }
  return {
    channels: key.split("|").map((entry) => {
      const [peak, rms] = entry.split(":");
      return {
        peakDb: parseNumber(peak) ?? SILENCE_DB,
        rmsDb: parseNumber(rms),
      };
    }),
  };
};

interface ChannelState {
  element: HTMLElement;
  peak: Ballistics;
  rms: Ballistics;
  level: number;
  rmsLevel: number;
  hold: number;
  zone: string;
  /** Null until first painted, so a new painter always writes it. */
  active: boolean | null;
}

/** Handed to the painter when it changes, so it never rebuilds the painter. */
interface MeterScale {
  maxDb: number;
  minDb: number;
  taper: Taper;
  zones: MeterZone[];
}

interface PainterOptions {
  ballistics: BallisticsInput;
  channels: Map<number, HTMLElement>;
  latest: RefObject<MeterFrame | null>;
  reducedMotion: boolean;
  root: RefObject<HTMLElement | null>;
  scale: MeterScale;
  visible: RefObject<boolean>;
}

interface MeterPainter {
  /** Paints one frame. Returns true while the meter needs another. */
  paint: (frameMs: number) => boolean;
  /** A new range, taper or zones, used from the next frame. */
  setScale: (scale: MeterScale) => void;
}

const silentLevel: ChannelLevel = { peakDb: SILENCE_DB };

const noop = () => {
  // Nothing to wake before the painter starts.
};

const writePosition = (
  element: HTMLElement,
  property: string,
  previous: number,
  next: number
) => {
  if (Math.abs(previous - next) > POSITION_EPSILON) {
    element.style.setProperty(property, next.toFixed(4));
    return next;
  }
  return previous;
};

interface ChannelPaint {
  /** The smoothed peak this frame, in dBFS. */
  db: number;
  /** Level, RMS and hold have all reached the input: nothing left to animate. */
  settled: boolean;
}

/**
 * Paints a meter's channels outside React: steps ballistics, writes CSS
 * variables and data attributes, and throttles ARIA updates. Returns true
 * while it needs another frame, so a meter that has settled, or is off
 * screen, stops costing frames until something wakes it.
 */
const createMeterPainter = (options: PainterOptions): MeterPainter => {
  const ballisticsOptions: BallisticsInput = options.reducedMotion
    ? "instant"
    : options.ballistics;
  const states = new Map<number, ChannelState>();
  const clock = createPainterClock();
  let { scale } = options;
  let clipUntil = 0;
  // Null until first painted: a painter rebuilt mid-clip must still clear
  // the attribute the previous one left.
  let clippingShown: boolean | null = null;
  let lastAriaMs = Number.NEGATIVE_INFINITY;
  let ariaShown: string | null = null;
  let rootZoneShown: string | null = null;
  let lastPaintMs = Number.NEGATIVE_INFINITY;

  const stateFor = (index: number, element: HTMLElement) => {
    const existing = states.get(index);
    if (existing && existing.element === element) {
      return existing;
    }
    const created: ChannelState = {
      active: null,
      element,
      hold: -1,
      level: -1,
      peak: createBallistics(ballisticsOptions),
      rms: createBallistics({
        ...resolveBallistics(ballisticsOptions),
        peakHoldMs: 0,
      }),
      rmsLevel: -1,
      zone: "",
    };
    states.set(index, created);
    return created;
  };

  const paintChannel = (
    index: number,
    element: HTMLElement,
    input: ChannelLevel,
    nowMs: number
  ): ChannelPaint => {
    const state = stateFor(index, element);
    const inputRmsDb = input.rmsDb ?? input.peakDb;
    const peak = state.peak.step(input.peakDb, nowMs);
    const rms = state.rms.step(inputRmsDb, nowMs);
    const { taper } = scale;
    const level = taper.toPosition(peak.db);
    const rmsLevel = taper.toPosition(rms.db);
    const hold = taper.toPosition(peak.holdDb);
    state.level = writePosition(element, "--meter-level", state.level, level);
    state.rmsLevel = writePosition(
      element,
      "--meter-rms",
      state.rmsLevel,
      rmsLevel
    );
    state.hold = writePosition(element, "--meter-hold", state.hold, hold);

    const zone = zoneForDb(peak.db, scale.zones);
    if (zone !== state.zone) {
      state.zone = zone;
      element.dataset.zone = zone;
    }
    const active = state.level > 0;
    if (active !== state.active) {
      state.active = active;
      element.toggleAttribute("data-active", active);
    }
    const settled =
      Math.abs(level - taper.toPosition(input.peakDb)) <= SETTLE_EPSILON &&
      Math.abs(rmsLevel - taper.toPosition(inputRmsDb)) <= SETTLE_EPSILON &&
      Math.abs(hold - level) <= SETTLE_EPSILON;
    return { db: peak.db, settled };
  };

  const paintRoot = (
    root: HTMLElement,
    loudest: number,
    nowMs: number,
    settled: boolean
  ) => {
    const clipping = nowMs < clipUntil;
    if (clipping !== clippingShown) {
      clippingShown = clipping;
      root.toggleAttribute("data-clipping", clipping);
    }
    const text = formatDb(loudest, { floorDb: scale.minDb });
    const zone = zoneForDb(loudest, scale.zones);
    if (text === ariaShown && zone === rootZoneShown) {
      return;
    }
    // Throttled while the level moves; a settled level is written at once,
    // so the value a screen reader finds is never a stale one.
    if (!settled && nowMs - lastAriaMs < ARIA_INTERVAL_MS) {
      return;
    }
    lastAriaMs = nowMs;
    ariaShown = text;
    rootZoneShown = zone;
    const clamped = Math.min(scale.maxDb, Math.max(scale.minDb, loudest));
    root.setAttribute("aria-valuenow", clamped.toFixed(1));
    root.setAttribute("aria-valuetext", text);
    root.dataset.zone = zone;
  };

  const paint = (frameMs: number): boolean => {
    // Hidden: sleep. Coming back into view wakes the painter.
    if (!options.visible.current) {
      return false;
    }
    const nowMs = clock(frameMs);
    if (
      options.reducedMotion &&
      nowMs - lastPaintMs < REDUCED_MOTION_INTERVAL_MS
    ) {
      return true;
    }
    lastPaintMs = nowMs;
    const frame = options.latest.current;
    let loudest = SILENCE_DB;
    let settled = true;
    let inputClipping = false;
    for (const [index, element] of options.channels) {
      const input = frame?.channels[index] ?? silentLevel;
      if (input.peakDb >= CLIP_THRESHOLD_DB) {
        clipUntil = nowMs + CLIP_HOLD_MS;
        inputClipping = true;
      }
      const painted = paintChannel(index, element, input, nowMs);
      loudest = Math.max(loudest, painted.db);
      settled &&= painted.settled;
    }
    const root = options.root.current;
    if (root) {
      paintRoot(root, loudest, nowMs, settled);
    }
    // A clip light counting down after the input dropped needs the frames
    // that turn it off; one held by a still-clipping input does not.
    const releasingClip = nowMs < clipUntil && !inputClipping;
    return !settled || releasingClip;
  };

  return {
    paint,
    setScale: (next) => {
      scale = next;
    },
  };
};

export const LevelMeterChannels = ({
  className,
  ...props
}: ComponentProps<"div">) => {
  const { orientation } = useLevelMeter("LevelMeterChannels");
  return (
    <div
      className={cn(
        "relative flex min-h-0 min-w-0 flex-1 gap-(--meter-gap)",
        orientation === "horizontal" ? "flex-col" : "h-full flex-row",
        className
      )}
      data-orientation={orientation}
      data-slot="level-meter-channels"
      {...props}
    />
  );
};

export interface LevelMeterChannelProps extends ComponentProps<"div"> {
  /** Which channel of the frames this track shows. Default 0. */
  index?: number;
}

export const LevelMeterChannel = ({
  index = 0,
  className,
  ref,
  ...props
}: LevelMeterChannelProps) => {
  const { orientation, registerChannel } = useLevelMeter("LevelMeterChannel");

  const setRef = useCallback(
    (node: HTMLDivElement | null) => {
      registerChannel(index, node);
      if (typeof ref === "function") {
        ref(node);
      } else if (ref) {
        ref.current = node;
      }
    },
    [index, ref, registerChannel]
  );

  return (
    <div
      className={cn(
        "flex min-h-0 min-w-0 [--meter-hold:0] [--meter-level:0] [--meter-rms:0]",
        orientation === "horizontal" ? "w-full" : "h-full",
        className
      )}
      data-index={index}
      data-orientation={orientation}
      data-slot="level-meter-channel"
      ref={setRef}
      {...props}
    />
  );
};

export const LevelMeterTrack = ({
  className,
  children,
  ...props
}: ComponentProps<"div">) => {
  const { orientation, variant } = useLevelMeter("LevelMeterTrack");
  const horizontal = orientation === "horizontal";

  return (
    <div
      className={cn(
        "bg-muted relative overflow-hidden rounded-full",
        horizontal
          ? "h-(--meter-thickness) w-full"
          : "h-full w-(--meter-thickness)",
        className
      )}
      data-orientation={orientation}
      data-slot="level-meter-track"
      {...props}
    >
      {variant === "segmented" ? (
        <div
          aria-hidden
          className="absolute inset-0 bg-(image:--meter-fill) mask-(--meter-mask) opacity-20"
          data-slot="level-meter-segments"
        />
      ) : null}
      {children}
    </div>
  );
};

export interface LevelMeterBarProps extends ComponentProps<"div"> {
  /** Which measurement this bar shows. Layer a `rms` and a `peak` bar for a dual meter. Default `peak`. */
  measure?: "peak" | "rms";
}

export const LevelMeterBar = ({
  measure = "peak",
  className,
  ...props
}: LevelMeterBarProps) => {
  const { orientation } = useLevelMeter("LevelMeterBar");
  const horizontal = orientation === "horizontal";

  return (
    <div
      aria-hidden
      className={cn(
        "absolute inset-0 overflow-hidden",
        measure === "rms"
          ? "[--meter-bar-level:var(--meter-rms)]"
          : "[--meter-bar-level:var(--meter-level)]",
        horizontal
          ? "translate-x-[calc((var(--meter-bar-level)_-_1)_*_100%)]"
          : "translate-y-[calc((1_-_var(--meter-bar-level))_*_100%)]",
        className
      )}
      data-measure={measure}
      data-slot="level-meter-bar"
      {...props}
    >
      <div
        className={cn(
          "absolute inset-0 bg-(image:--meter-fill) mask-(--meter-mask)",
          horizontal
            ? "translate-x-[calc((1_-_var(--meter-bar-level))_*_100%)]"
            : "translate-y-[calc((var(--meter-bar-level)_-_1)_*_100%)]"
        )}
        data-slot="level-meter-fill"
      />
    </div>
  );
};

export const LevelMeterHold = ({
  className,
  ...props
}: ComponentProps<"div">) => {
  const { orientation } = useLevelMeter("LevelMeterHold");
  const horizontal = orientation === "horizontal";

  return (
    <div
      aria-hidden
      className={cn(
        "pointer-events-none absolute inset-0 opacity-[calc(var(--meter-hold)_*_50)]",
        horizontal
          ? "translate-x-[calc((var(--meter-hold)_-_1)_*_100%)]"
          : "translate-y-[calc((1_-_var(--meter-hold))_*_100%)]"
      )}
      data-slot="level-meter-hold"
      {...props}
    >
      <div
        className={cn(
          "bg-foreground/80 absolute",
          horizontal ? "inset-y-0 right-0 w-0.5" : "inset-x-0 top-0 h-0.5",
          className
        )}
      />
    </div>
  );
};

export type LevelMeterScaleProps = Omit<
  DbScaleProps,
  "minDb" | "maxDb" | "taper" | "orientation"
>;

export const LevelMeterScale = ({
  className,
  ...props
}: LevelMeterScaleProps) => {
  const { maxDb, minDb, orientation, taper } = useLevelMeter("LevelMeterScale");
  // Horizontal meters reserve space below the tracks for the scale.
  return (
    <DbScale
      className={cn(
        orientation === "horizontal" &&
          "absolute top-[calc(100%+var(--meter-gap))] left-0 h-(--meter-scale-size)",
        className
      )}
      maxDb={maxDb}
      minDb={minDb}
      orientation={orientation}
      taper={taper}
      {...props}
    />
  );
};

export type LevelMeterValueProps = Omit<DbReadoutProps, "source" | "value">;

export const LevelMeterValue = (props: LevelMeterValueProps) => {
  const { declared, frames, minDb } = useLevelMeter("LevelMeterValue");
  // Declarative levels only change on render, so show them as a value. A
  // stream keeps its live readout, which falls to −∞ when it stops.
  const value = declared
    ? readChannel(declared, props.measure ?? "peak", props.channel ?? "max")
    : undefined;
  return (
    <DbReadout
      className="text-muted-foreground text-xs"
      floorDb={minDb}
      source={declared ? null : frames}
      value={value}
      {...props}
    />
  );
};

export type LevelMeterClipProps = Omit<ClipIndicatorProps, "source">;

export const LevelMeterClip = (props: LevelMeterClipProps) => {
  const { frames } = useLevelMeter("LevelMeterClip");
  return <ClipIndicator source={frames} {...props} />;
};

const levelMeterVariants = cva(
  // Animated bars and peak markers must not become the page's scroll anchor.
  "group/level-meter flex gap-2 [--meter-gap:0.25rem] [overflow-anchor:none] data-dimmed:opacity-50",
  {
    defaultVariants: {
      orientation: "horizontal",
      size: "default",
    },
    variants: {
      orientation: {
        horizontal:
          "w-full flex-row items-center [--meter-scale-size:1rem] has-[[data-slot=db-scale]]:pb-[calc(var(--meter-scale-size)+var(--meter-gap))]",
        vertical: "min-h-32 flex-col items-center",
      },
      size: {
        default: "[--meter-thickness:0.5rem]",
        lg: "[--meter-thickness:0.75rem]",
        sm: "[--meter-thickness:0.25rem]",
      },
    },
  }
);

export interface LevelMeterProps
  extends
    ComponentProps<"div">,
    Omit<VariantProps<typeof levelMeterVariants>, "orientation"> {
  /** A meter source; the meter subscribes and paints itself without re-rendering React. */
  source?: FrameSource<MeterFrame> | null;
  /** Mono peak level in dBFS, for declarative use. */
  peakDb?: number;
  /** Mono RMS level in dBFS, for declarative use. */
  rmsDb?: number;
  /** Levels per channel, for declarative multi-channel use. */
  channels?: ChannelLevel[];
  /** Tracks to render before data arrives. Default 1. */
  channelCount?: number;
  /** Bottom of the displayed range. Default −60. */
  minDb?: number;
  /** Top of the displayed range. Default 0. */
  maxDb?: number;
  /** Colour zones. Default ok / warn from −20 / clip from −9. */
  zones?: MeterZone[];
  /** How the meter moves. Default `peak`. */
  ballistics?: BallisticsInput;
  /** Scale law. Default `linear`. */
  taper?: TaperInput;
  orientation?: Orientation;
  /** `segmented` is an LED ladder. Default `solid`. */
  variant?: LevelMeterVariant;
  /** Segments for the `segmented` variant. Default 24. */
  segments?: number;
  actionsRef?: Ref<LevelMeterActions>;
}

interface MeterSettings {
  orientation: Orientation;
  size: AudioSize;
  minDb: number;
  maxDb: number;
  zones: MeterZone[];
  ballistics: BallisticsInput;
  dimmed: boolean;
}

/** Explicit props win over the surrounding mixer or strip. */
const useMeterSettings = (props: Partial<MeterSettings>): MeterSettings => {
  const config = useAudioConfig();
  return {
    ballistics: props.ballistics ?? config.ballistics ?? "peak",
    dimmed: config.dimmed ?? false,
    maxDb: props.maxDb ?? config.maxDb ?? DEFAULT_MAX_DB,
    minDb: props.minDb ?? config.minDb ?? DEFAULT_MIN_DB,
    orientation: props.orientation ?? config.orientation ?? "horizontal",
    size: props.size ?? config.size ?? "default",
    zones: props.zones ?? config.zones ?? DEFAULT_ZONES,
  };
};

export const LevelMeter = ({
  source,
  peakDb,
  rmsDb,
  channels,
  channelCount: channelCountProp,
  minDb: minDbProp,
  maxDb: maxDbProp,
  zones: zonesProp,
  ballistics: ballisticsProp,
  taper = "linear",
  orientation: orientationProp,
  variant = "solid",
  segments = DEFAULT_SEGMENTS,
  size: sizeProp,
  actionsRef,
  className,
  children,
  ref,
  style,
  ...props
}: LevelMeterProps) => {
  const settings = useMeterSettings({
    ballistics: ballisticsProp,
    maxDb: maxDbProp,
    minDb: minDbProp,
    orientation: orientationProp,
    size: sizeProp ?? undefined,
    zones: zonesProp,
  });
  const { maxDb, minDb, orientation, zones } = settings;
  const reducedMotion = useReducedMotion();
  const frames = useMemo(() => createFrameEmitter<MeterFrame>(), []);
  const latestRef = useRef<MeterFrame | null>(null);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const channelsRef = useRef(new Map<number, HTMLElement>());
  // Wakes the painter when something changed. A settled meter sleeps.
  const wakeRef = useRef<() => void>(noop);
  const visibleRef = useVisibility(rootRef, (visible) => {
    if (visible) {
      wakeRef.current();
    }
  });
  const [observedCount, setObservedCount] = useState<number | null>(null);

  const accept = useCallback(
    (frame: MeterFrame) => {
      latestRef.current = frame;
      frames.emit(frame);
      wakeRef.current();
    },
    [frames]
  );

  const acceptAndCount = useCallback(
    (frame: MeterFrame) => {
      accept(frame);
      const count = frame.channels.length;
      if (count > 0) {
        setObservedCount((previous) => (previous === count ? previous : count));
      }
    },
    [accept]
  );

  useFrameSource(source, acceptAndCount);

  const declarativeKey = serializeLevels(channels, peakDb, rmsDb);
  let declaredCount: number | null = null;
  if (channels) {
    declaredCount = channels.length;
  } else if (declarativeKey !== "") {
    declaredCount = 1;
  }
  const channelCount = declaredCount ?? observedCount ?? channelCountProp ?? 1;
  const declared = useMemo(
    () => (source ? null : parseLevels(declarativeKey)),
    [declarativeKey, source]
  );

  useEffect(() => {
    const frame = parseLevels(declarativeKey);
    if (frame) {
      accept(frame);
    }
  }, [accept, declarativeKey]);

  const taperFn = useMemo(
    () => resolveTaper(taper, minDb, maxDb),
    [taper, minDb, maxDb]
  );

  const registerChannel = useCallback(
    (index: number, element: HTMLElement | null) => {
      if (element) {
        channelsRef.current.set(index, element);
      } else {
        channelsRef.current.delete(index);
      }
      wakeRef.current();
    },
    []
  );

  const ballisticsKey = JSON.stringify(
    typeof settings.ballistics === "string"
      ? settings.ballistics
      : resolveBallistics(settings.ballistics)
  );

  // Scale changes (an inline zones array, a new range) reach the painter on
  // its next frame instead of rebuilding it and resetting the ballistics.
  const scale = useMemo<MeterScale>(
    () => ({ maxDb, minDb, taper: taperFn, zones }),
    [maxDb, minDb, taperFn, zones]
  );
  const readScale = useEffectEvent(() => scale);
  const painterRef = useRef<MeterPainter | null>(null);

  useEffect(() => {
    const painter = createMeterPainter({
      ballistics: JSON.parse(ballisticsKey) as BallisticsInput,
      channels: channelsRef.current,
      latest: latestRef,
      reducedMotion,
      root: rootRef,
      scale: readScale(),
      visible: visibleRef,
    });
    const task = createFrameTask(painter.paint);
    painterRef.current = painter;
    wakeRef.current = task.wake;
    return () => {
      painterRef.current = null;
      wakeRef.current = noop;
      task.stop();
    };
  }, [ballisticsKey, reducedMotion, visibleRef]);

  // A new range or zones array reaches the painter, and repaints a meter that
  // had settled.
  useEffect(() => {
    painterRef.current?.setScale(scale);
    wakeRef.current();
  }, [scale]);

  useImperativeHandle(
    actionsRef,
    () => ({
      paint: acceptAndCount,
      reset: () => {
        accept({ channels: [] });
      },
    }),
    [accept, acceptAndCount]
  );

  const zoneFill = useMemo(
    () => buildZoneFill(zones, taperFn, orientation, variant),
    [orientation, taperFn, variant, zones]
  );
  const segmentMask =
    variant === "segmented" ? buildSegmentMask(orientation, segments) : "none";

  const contextValue = useMemo<LevelMeterContextValue>(
    () => ({
      channelCount,
      declared,
      frames,
      maxDb,
      minDb,
      orientation,
      registerChannel,
      taper: taperFn,
      variant,
      zones,
    }),
    [
      channelCount,
      declared,
      frames,
      maxDb,
      minDb,
      orientation,
      registerChannel,
      taperFn,
      variant,
      zones,
    ]
  );

  const setRootRef = useCallback(
    (node: HTMLDivElement | null) => {
      rootRef.current = node;
      if (typeof ref === "function") {
        ref(node);
      } else if (ref) {
        ref.current = node;
      }
    },
    [ref]
  );

  return (
    <LevelMeterContext.Provider value={contextValue}>
      <div
        aria-valuemax={maxDb}
        aria-valuemin={minDb}
        aria-valuenow={minDb}
        className={cn(
          levelMeterVariants({ orientation, size: settings.size }),
          className
        )}
        data-dimmed={settings.dimmed ? "" : undefined}
        data-orientation={orientation}
        data-size={settings.size}
        data-slot="level-meter"
        data-variant={variant}
        ref={setRootRef}
        role="meter"
        style={
          {
            "--meter-fill": zoneFill,
            "--meter-mask": segmentMask,
            ...style,
          } as CSSProperties
        }
        {...props}
      >
        {children ?? (
          <LevelMeterChannels>
            {Array.from({ length: channelCount }, (_, index) => (
              <LevelMeterChannel index={index} key={`channel-${index}`}>
                <LevelMeterTrack>
                  <LevelMeterBar />
                  <LevelMeterHold />
                </LevelMeterTrack>
              </LevelMeterChannel>
            ))}
          </LevelMeterChannels>
        )}
      </div>
    </LevelMeterContext.Provider>
  );
};

export { levelMeterVariants };

import { dbToGain, gainToDb } from "./audio-meters-decibels";

/** How a meter moves between readings. All times are in milliseconds. */
export interface BallisticsOptions {
  /** Time constant for rising levels. 0 jumps instantly. */
  attackMs: number;
  /** Time constant for falling levels. 0 drops instantly. */
  releaseMs: number;
  /** How long the peak-hold marker stays before it starts to fall. 0 disables it. */
  peakHoldMs: number;
  /** Time constant for the peak-hold marker's fall. */
  peakReleaseMs: number;
}

export const BALLISTICS = {
  instant: { attackMs: 0, peakHoldMs: 0, peakReleaseMs: 0, releaseMs: 0 },
  peak: { attackMs: 15, peakHoldMs: 1200, peakReleaseMs: 600, releaseMs: 350 },
  vu: { attackMs: 300, peakHoldMs: 0, peakReleaseMs: 300, releaseMs: 300 },
} as const satisfies Record<string, BallisticsOptions>;

export type BallisticsPreset = keyof typeof BALLISTICS;

export type BallisticsInput = BallisticsPreset | Partial<BallisticsOptions>;

export const resolveBallistics = (
  input: BallisticsInput = "peak"
): BallisticsOptions => {
  if (typeof input === "string") {
    return BALLISTICS[input];
  }
  return { ...BALLISTICS.peak, ...input };
};

export interface BallisticsState {
  /** The smoothed level in dBFS. */
  db: number;
  /** The peak-hold level in dBFS. */
  holdDb: number;
}

export interface Ballistics {
  step: (inputDb: number, nowMs: number) => BallisticsState;
  reset: () => void;
}

const smoothingFactor = (elapsedMs: number, timeConstantMs: number): number => {
  if (timeConstantMs <= 0) {
    return 1;
  }
  return 1 - Math.exp(-elapsedMs / timeConstantMs);
};

/**
 * Creates a meter ballistics integrator. Smoothing runs on linear amplitude,
 * so a falling level drops at a steady rate in dB, like a hardware meter.
 */
export const createBallistics = (input?: BallisticsInput): Ballistics => {
  const options = resolveBallistics(input);
  let amplitude = 0;
  let holdAmplitude = 0;
  let holdUntilMs = 0;
  let lastMs: number | null = null;

  const reset = () => {
    amplitude = 0;
    holdAmplitude = 0;
    holdUntilMs = 0;
    lastMs = null;
  };

  const step = (inputDb: number, nowMs: number): BallisticsState => {
    const target = dbToGain(inputDb);

    if (lastMs === null) {
      amplitude = target;
    } else {
      const elapsedMs = Math.max(0, nowMs - lastMs);
      const timeConstant =
        target > amplitude ? options.attackMs : options.releaseMs;
      amplitude +=
        (target - amplitude) * smoothingFactor(elapsedMs, timeConstant);
    }

    if (options.peakHoldMs <= 0) {
      holdAmplitude = amplitude;
    } else if (amplitude >= holdAmplitude) {
      holdAmplitude = amplitude;
      holdUntilMs = nowMs + options.peakHoldMs;
    } else if (nowMs > holdUntilMs && lastMs !== null) {
      const elapsedMs = Math.max(0, nowMs - Math.max(lastMs, holdUntilMs));
      holdAmplitude -=
        (holdAmplitude - amplitude) *
        smoothingFactor(elapsedMs, options.peakReleaseMs);
    }

    lastMs = nowMs;
    return { db: gainToDb(amplitude), holdDb: gainToDb(holdAmplitude) };
  };

  return { reset, step };
};

"use client";

import { useImperativeHandle } from "react";
import type { ComponentProps, Ref } from "react";

import { useClipHold } from "./audio-meters-use-clip-hold";
import { useFrameSource } from "./audio-meters-use-frame-source";
import { SILENCE_DB } from "./audio-meters-decibels";
import type { FrameSource, MeterFrame } from "./audio-meters-types";
import { CLIP_HOLD_MS, CLIP_THRESHOLD_DB } from "./audio-meters-zones";
import { cn } from "@/lib/utils";

export interface ClipIndicatorActions {
  /** Feed a level reading. */
  report: (db: number) => void;
  /** Turn the light off and clear the count. */
  reset: () => void;
}

// Ported without @base-ui/react: upstream renders through useRender/mergeProps;
// here it is a plain <button> carrying the same data-slot / data-clipping hooks.
export interface ClipIndicatorProps extends ComponentProps<"button"> {
  /** Controlled clip state. When set, the component does no detection. */
  clipping?: boolean;
  /** A meter source; the indicator detects clipping itself. */
  source?: FrameSource<MeterFrame> | null;
  /** Levels at or above this count as a clip. Default −1 dBFS. */
  thresholdDb?: number;
  /** How long the light stays on. `Infinity` latches until reset. Default 1500 ms. */
  holdMs?: number;
  onClippingChange?: (clipping: boolean) => void;
  /** Show the number of clips next to the light. Default false. */
  showCount?: boolean;
  actionsRef?: Ref<ClipIndicatorActions>;
}

const loudestPeak = (frame: MeterFrame) => {
  let loudest = SILENCE_DB;
  for (const level of frame.channels) {
    loudest = Math.max(loudest, level.peakDb);
  }
  return loudest;
};

export const ClipIndicator = ({
  clipping: clippingProp,
  source,
  thresholdDb = CLIP_THRESHOLD_DB,
  holdMs = CLIP_HOLD_MS,
  onClippingChange,
  showCount = false,
  actionsRef,
  className,
  children,
  onClick,
  ...props
}: ClipIndicatorProps) => {
  const hold = useClipHold({ holdMs, onClippingChange, thresholdDb });
  const clipping = clippingProp ?? hold.clipping;

  useFrameSource(source, (frame) => {
    hold.report(loudestPeak(frame));
  });

  useImperativeHandle(
    actionsRef,
    () => ({ report: hold.report, reset: hold.reset }),
    [hold.report, hold.reset]
  );

  const content = (
    <>
      {children ?? (
        <span
          className="bg-muted-foreground/30 group-data-clipping/clip-indicator:bg-(--meter-clip) size-2 shrink-0 rounded-full transition-colors"
          data-slot="clip-indicator-light"
        />
      )}
      {showCount ? (
        <span className="tabular-nums" data-slot="clip-indicator-count">
          {hold.count}
        </span>
      ) : null}
      <span aria-live="polite" className="sr-only">
        {clipping ? "Clipping" : ""}
      </span>
    </>
  );

  return (
    <button
      aria-label={
        clipping ? "Clipping. Reset clip indicator" : "Clip indicator"
      }
      className={cn(
        "group/clip-indicator text-muted-foreground hover:bg-muted focus-visible:ring-ring/30 data-clipping:text-(--meter-clip-foreground) relative inline-flex h-5 shrink-0 items-center justify-center gap-1 rounded-full px-1 text-xs font-medium transition-colors outline-none after:absolute after:-inset-1 focus-visible:ring-3 pointer-coarse:after:-inset-2.5",
        className
      )}
      data-clipping={clipping ? "" : undefined}
      data-slot="clip-indicator"
      type="button"
      {...props}
      onClick={(event) => {
        hold.reset();
        onClick?.(event);
      }}
    >
      {content}
    </button>
  );
};

"use client";

import { useEffect, useRef } from "react";
import { useEffectEvent } from "./audio-meters-use-effect-event";
import type { ComponentProps, CSSProperties } from "react";

import { useFrameSource } from "./audio-meters-use-frame-source";
import { formatDb, SILENCE_DB } from "./audio-meters-decibels";
import type { FrameSource, MeterFrame, MeterZone } from "./audio-meters-types";
import { DEFAULT_ZONES, zoneForDb } from "./audio-meters-zones";
import { cn } from "@/lib/utils";

const DEFAULT_INTERVAL_MS = 250;
const DEFAULT_FLOOR_DB = -60;
/** Two-digit levels, the widest a meter usually shows, on either side of 0. */
const WIDEST_MAGNITUDE_DB = 88.8;

const noop = () => {
  // Nothing to wake before the ticker starts.
};

/**
 * An interval that stops itself once `step` reports nothing left to do, and
 * that `wake` starts again: a readout whose source went quiet costs no timer.
 */
const createTicker = (step: () => boolean, intervalMs: number) => {
  let timer: ReturnType<typeof setInterval> | null = null;
  const stop = () => {
    if (timer !== null) {
      clearInterval(timer);
      timer = null;
    }
  };
  const wake = () => {
    if (timer === null) {
      timer = setInterval(() => {
        if (!step()) {
          stop();
        }
      }, intervalMs);
    }
  };
  return { stop, wake };
};

export interface DbReadoutProps extends Omit<
  ComponentProps<"span">,
  "children"
> {
  /** A level in dB, for declarative use. */
  value?: number;
  /** A meter source; the readout updates itself without re-rendering React. */
  source?: FrameSource<MeterFrame> | null;
  /** Which measurement to show. Default `peak`. */
  measure?: "peak" | "rms";
  /** A channel index, or `max` for the loudest channel. Default `max`. */
  channel?: number | "max";
  /** How often the text changes. Default 250 ms. */
  intervalMs?: number;
  /** Show the highest value seen within this window. Default 0. */
  holdMs?: number;
  /** Digits after the decimal point. Default 1. */
  decimals?: number;
  /** Append " dB". Default true. */
  unit?: boolean;
  /** At or below this level, show "−∞". Default −60. */
  floorDb?: number;
  /** Zones used for `data-zone`. */
  zones?: MeterZone[];
  /** Replaces all formatting. */
  format?: (db: number) => string;
}

/** The level a readout shows from one frame. */
export const readChannel = (
  frame: MeterFrame,
  measure: "peak" | "rms",
  channel: number | "max"
) => {
  const read = (index: number) => {
    const level = frame.channels[index];
    if (!level) {
      return SILENCE_DB;
    }
    return measure === "rms" ? (level.rmsDb ?? level.peakDb) : level.peakDb;
  };
  if (channel !== "max") {
    return read(channel);
  }
  let loudest = SILENCE_DB;
  for (let index = 0; index < frame.channels.length; index += 1) {
    loudest = Math.max(loudest, read(index));
  }
  return loudest;
};

export const DbReadout = ({
  value,
  source,
  measure = "peak",
  channel = "max",
  intervalMs = DEFAULT_INTERVAL_MS,
  holdMs = 0,
  decimals = 1,
  unit = true,
  floorDb = DEFAULT_FLOOR_DB,
  zones = DEFAULT_ZONES,
  format,
  className,
  style,
  ...props
}: DbReadoutProps) => {
  const elementRef = useRef<HTMLSpanElement>(null);
  const peakRef = useRef(SILENCE_DB);
  const peakAtRef = useRef(0);
  const shownRef = useRef<string | null>(null);

  const render = (db: number) =>
    format ? format(db) : formatDb(db, { decimals, floorDb, unit });

  const initialDb = value ?? SILENCE_DB;
  // Size for the widest text the readout can show, so it never changes width.
  // Values at or below the floor read as −∞, so measure just above it too.
  const justAboveFloor = Number.isFinite(floorDb)
    ? floorDb + 10 ** -decimals
    : -WIDEST_MAGNITUDE_DB;
  const widest = Math.max(
    ...[
      SILENCE_DB,
      justAboveFloor,
      -WIDEST_MAGNITUDE_DB,
      WIDEST_MAGNITUDE_DB,
    ].map((db) => render(db).length)
  );

  // Frames since the last tick, and the wake for a ticker that went quiet.
  const freshRef = useRef(false);
  const wakeRef = useRef<() => void>(noop);

  useFrameSource(source, (frame) => {
    const db = readChannel(frame, measure, channel);
    const now = performance.now();
    if (db >= peakRef.current || now - peakAtRef.current > holdMs) {
      peakRef.current = db;
      peakAtRef.current = now;
    }
    freshRef.current = true;
    wakeRef.current();
  });

  // Reads the latest props on each tick, so an inline format or zones array
  // doesn't restart the timer (and freeze the readout) on every render.
  // Returns whether the ticker still has work: a quiet source whose readout
  // stopped changing lets it stop, and the next frame starts it again.
  const tick = useEffectEvent((): boolean => {
    const element = elementRef.current;
    if (!element) {
      return false;
    }
    const db = peakRef.current;
    const text = render(db);
    const changed = text !== shownRef.current;
    if (changed) {
      shownRef.current = text;
      if (element.firstChild) {
        element.firstChild.nodeValue = text;
      } else {
        element.textContent = text;
      }
      element.dataset.zone = zoneForDb(db, zones);
      element.toggleAttribute("data-silent", db <= floorDb);
    }
    // Without a hold, a source that stops sending frames falls to −∞.
    if (holdMs === 0) {
      peakRef.current = SILENCE_DB;
    }
    const fresh = freshRef.current;
    freshRef.current = false;
    return changed || fresh;
  });

  useEffect(() => {
    if (!source) {
      return;
    }
    // The first tick always writes, whatever the span shows now.
    shownRef.current = null;
    const ticker = createTicker(() => tick(), intervalMs);
    wakeRef.current = ticker.wake;
    ticker.wake();
    return () => {
      wakeRef.current = noop;
      ticker.stop();
    };
  }, [intervalMs, source]);

  // The ticker writes text React does not know about. Switching between a
  // source and a value swaps the span, so a value never shows the last live
  // level and a returning source starts from a fresh first paint.
  return (
    <span
      key={source ? "source" : "value"}
      className={cn(
        "inline-block min-w-(--db-readout-width) text-end font-mono tabular-nums",
        className
      )}
      data-silent={initialDb <= floorDb ? "" : undefined}
      data-slot="db-readout"
      data-zone={zoneForDb(initialDb, zones)}
      ref={elementRef}
      style={{ "--db-readout-width": `${widest}ch`, ...style } as CSSProperties}
      {...props}
    >
      {render(initialDb)}
    </span>
  );
};

"use client";

import {
  createContext,
  useCallback,
  useContext,
  useLayoutEffect,
  useMemo,
  useRef,
} from "react";
import type { ComponentProps, CSSProperties } from "react";

import { useAudioConfig } from "./audio-meters-use-audio-config";
import { DEFAULT_MAX_DB, DEFAULT_MIN_DB, formatDb } from "./audio-meters-decibels";
import { resolveTaper } from "./audio-meters-taper";
import type { TaperInput } from "./audio-meters-taper";
import type { Orientation, Taper } from "./audio-meters-types";
import { cn } from "@/lib/utils";

const DEFAULT_TICKS = [12, 6, 0, -6, -12, -18, -24, -36, -48, -60, -72, -90];
const EDGE = 0.02;
/** Space kept between two labels, in pixels. */
const LABEL_GAP = 3;
const MAJOR_STEP = 12;

/**
 * Hides labels that would touch a more important one, so narrow scales stay
 * readable: 0 dB first, then the ends, then multiples of 12, then the rest.
 */
export const thinDbScaleLabels = (scale: HTMLElement) => {
  const horizontal = scale.dataset.orientation !== "vertical";
  const entries: { label: HTMLElement; rank: number; value: number }[] = [];
  for (const tick of scale.querySelectorAll<HTMLElement>(
    "[data-slot=db-scale-tick]"
  )) {
    const label = tick.querySelector<HTMLElement>("[data-slot=db-scale-label]");
    if (label) {
      delete label.dataset.hidden;
      entries.push({ label, rank: 3, value: Number(tick.dataset.value) });
    }
  }
  const values = entries.map((entry) => entry.value);
  const top = Math.max(...values);
  const bottom = Math.min(...values);
  for (const entry of entries) {
    if (entry.value === 0) {
      entry.rank = 0;
    } else if (entry.value === top || entry.value === bottom) {
      entry.rank = 1;
    } else if (entry.value % MAJOR_STEP === 0) {
      entry.rank = 2;
    }
  }
  entries.sort((a, b) => a.rank - b.rank || b.value - a.value);

  const kept: [number, number][] = [];
  for (const { label } of entries) {
    const rect = label.getBoundingClientRect();
    // Not laid out, so there is nothing to compare.
    if (rect.width === 0 && rect.height === 0) {
      continue;
    }
    const start = horizontal ? rect.left : rect.top;
    const end = horizontal ? rect.right : rect.bottom;
    const collides = kept.some(
      ([keptStart, keptEnd]) =>
        start < keptEnd + LABEL_GAP && end > keptStart - LABEL_GAP
    );
    if (collides) {
      label.dataset.hidden = "";
    } else {
      kept.push([start, end]);
    }
  }
};

const defaultFormat = (db: number) =>
  formatDb(db, { decimals: 0, unit: false });

interface DbScaleContextValue {
  orientation: Orientation;
  side: "start" | "end";
  labels: boolean;
  taper: Taper;
  format: (db: number) => string;
}

const DbScaleContext = createContext<DbScaleContextValue | null>(null);

const useDbScale = () => {
  const context = useContext(DbScaleContext);
  if (!context) {
    throw new Error("DbScaleTick must be used inside DbScale.");
  }
  return context;
};

/** Keeps labels at the ends of the scale inside it. */
const alignClass = (orientation: Orientation, position: number) => {
  if (orientation === "vertical") {
    if (position < EDGE) {
      return "translate-y-0";
    }
    return position > 1 - EDGE ? "translate-y-full" : "translate-y-1/2";
  }
  if (position < EDGE) {
    return "translate-x-0";
  }
  return position > 1 - EDGE ? "-translate-x-full" : "-translate-x-1/2";
};

const markClass = (horizontal: boolean, major: boolean) => {
  if (horizontal) {
    return major ? "h-1.5 w-px" : "h-1 w-px";
  }
  return major ? "h-px w-1.5" : "h-px w-1";
};

export interface DbScaleTickProps extends ComponentProps<"div"> {
  value: number;
  /** Major ticks are longer. Default true. */
  major?: boolean;
}

export const DbScaleTick = ({
  value,
  major = true,
  className,
  children,
  style,
  ...props
}: DbScaleTickProps) => {
  const { format, labels, orientation, side, taper } = useDbScale();
  const position = taper.toPosition(value);
  const horizontal = orientation === "horizontal";
  const reversed = side === "start";

  return (
    <div
      className={cn(
        "absolute flex items-center gap-0.5",
        horizontal
          ? "top-0 left-(--tick-position) h-full flex-col"
          : "bottom-(--tick-position) left-0 w-full flex-row",
        reversed && (horizontal ? "flex-col-reverse" : "flex-row-reverse"),
        alignClass(orientation, position),
        className
      )}
      data-major={major ? "" : undefined}
      data-slot="db-scale-tick"
      data-value={value}
      style={
        { "--tick-position": `${position * 100}%`, ...style } as CSSProperties
      }
      {...props}
    >
      <span
        className={cn("bg-border shrink-0", markClass(horizontal, major))}
        data-slot="db-scale-mark"
      />
      {labels ? (
        <span
          className={cn(
            "data-hidden:invisible",
            // Right-aligned so the last digits of a vertical scale line up.
            !horizontal && "flex-1 text-end"
          )}
          data-slot="db-scale-label"
        >
          {children ?? format(value)}
        </span>
      ) : null}
    </div>
  );
};

export interface DbScaleProps extends ComponentProps<"div"> {
  /** Bottom of the range. Default −60, or the surrounding meter's range. */
  minDb?: number;
  /** Top of the range. Default 0, or the surrounding meter's range. */
  maxDb?: number;
  /** Tick values. Default: common values inside the range. */
  ticks?: number[];
  /** Position law, so ticks line up with a fader or meter using the same taper. */
  taper?: TaperInput;
  orientation?: Orientation;
  /** Which side of the tick marks the labels sit on. Default `end`. */
  side?: "start" | "end";
  /** Show labels. Default true. */
  labels?: boolean;
  format?: (db: number) => string;
}

export const DbScale = ({
  minDb: minDbProp,
  maxDb: maxDbProp,
  ticks,
  taper = "linear",
  orientation: orientationProp,
  side = "end",
  labels = true,
  format = defaultFormat,
  className,
  children,
  ref,
  ...props
}: DbScaleProps) => {
  const config = useAudioConfig();
  const minDb = minDbProp ?? config.minDb ?? DEFAULT_MIN_DB;
  const maxDb = maxDbProp ?? config.maxDb ?? DEFAULT_MAX_DB;
  const orientation = orientationProp ?? config.orientation ?? "horizontal";

  const value = useMemo<DbScaleContextValue>(
    () => ({
      format,
      labels,
      orientation,
      side,
      taper: resolveTaper(taper, minDb, maxDb),
    }),
    [format, labels, maxDb, minDb, orientation, side, taper]
  );

  const values =
    ticks ?? DEFAULT_TICKS.filter((tick) => tick >= minDb && tick <= maxDb);

  const scaleRef = useRef<HTMLDivElement | null>(null);
  const setScaleRef = useCallback(
    (node: HTMLDivElement | null) => {
      scaleRef.current = node;
      if (typeof ref === "function") {
        ref(node);
      } else if (ref) {
        ref.current = node;
      }
    },
    [ref]
  );

  // Re-check label collisions when the scale resizes or its ticks change.
  useLayoutEffect(() => {
    const scale = scaleRef.current;
    if (!(scale && labels)) {
      return;
    }
    let cancelled = false;
    const thin = () => thinDbScaleLabels(scale);
    thin();
    const resize =
      typeof ResizeObserver === "undefined" ? null : new ResizeObserver(thin);
    resize?.observe(scale);
    // Only style changes: hiding a label must not trigger another pass.
    const ticksChanged = new MutationObserver(thin);
    ticksChanged.observe(scale, {
      attributeFilter: ["style"],
      characterData: true,
      childList: true,
      subtree: true,
    });
    const afterFonts = async () => {
      await document.fonts?.ready;
      if (!cancelled) {
        thin();
      }
    };
    afterFonts();
    return () => {
      cancelled = true;
      resize?.disconnect();
      ticksChanged.disconnect();
    };
  }, [labels]);

  return (
    <DbScaleContext.Provider value={value}>
      <div
        aria-hidden
        className={cn(
          "text-muted-foreground relative shrink-0 text-[0.625rem] leading-none tabular-nums select-none",
          orientation === "horizontal" ? "h-4 w-full" : "h-full w-7",
          className
        )}
        data-orientation={orientation}
        data-side={side}
        data-slot="db-scale"
        ref={setScaleRef}
        {...props}
      >
        {children ??
          values.map((tick) => <DbScaleTick key={tick} value={tick} />)}
      </div>
    </DbScaleContext.Provider>
  );
};

/** Default bottom of a meter's range, in dBFS. */
export const DEFAULT_MIN_DB = -60;
/** Default top of a meter's range, in dBFS. */
export const DEFAULT_MAX_DB = 0;
/** Digital silence. */
export const SILENCE_DB = Number.NEGATIVE_INFINITY;

const AMPLITUDE_DB_FACTOR = 20;
const MINUS_SIGN = "−";
const INFINITY_SIGN = "∞";

export const clamp = (value: number, min: number, max: number): number =>
  Math.min(max, Math.max(min, value));

/** Decibels to linear gain. `-Infinity` gives 0. */
export const dbToGain = (db: number): number => {
  if (db === SILENCE_DB) {
    return 0;
  }
  return 10 ** (db / AMPLITUDE_DB_FACTOR);
};

/** Linear gain to decibels. 0 (or less) gives `-Infinity`. */
export const gainToDb = (gain: number): number => {
  if (gain <= 0) {
    return SILENCE_DB;
  }
  return AMPLITUDE_DB_FACTOR * Math.log10(gain);
};

/** dBFS to a 0..1 level, linear in dB over `minDb..maxDb`, clamped. */
export const dbToLevel = (
  db: number,
  minDb: number = DEFAULT_MIN_DB,
  maxDb: number = DEFAULT_MAX_DB
): number => {
  if (!(db > minDb)) {
    return 0;
  }
  return clamp((db - minDb) / (maxDb - minDb), 0, 1);
};

/** A 0..1 level back to dBFS over `minDb..maxDb`. The inverse of `dbToLevel`. */
export const levelToDb = (
  level: number,
  minDb: number = DEFAULT_MIN_DB,
  maxDb: number = DEFAULT_MAX_DB
): number => minDb + clamp(level, 0, 1) * (maxDb - minDb);

/**
 * Clamps a dB value to a range. With `allowSilence`, `-Infinity` passes
 * through instead of becoming `minDb`.
 */
export const clampDb = (
  db: number,
  minDb: number,
  maxDb: number,
  options: { allowSilence?: boolean } = {}
): number => {
  if (db === SILENCE_DB && options.allowSilence) {
    return SILENCE_DB;
  }
  if (Number.isNaN(db)) {
    return minDb;
  }
  return clamp(db, minDb, maxDb);
};

export interface FormatDbOptions {
  /** Digits after the decimal point. Default 1. */
  decimals?: number;
  /** Append " dB". Default true. */
  unit?: boolean;
  /**
   * `auto` shows "+" for positive values and "−" for negative ones,
   * `negative` only shows "−", `never` shows no sign. Default `auto`.
   */
  sign?: "auto" | "negative" | "never";
  /** At or below this value, show "−∞". Default `-Infinity`. */
  floorDb?: number;
}

/** Formats decibels for display: "−12.3 dB", "+3.0 dB", "−∞ dB". */
export const formatDb = (db: number, options: FormatDbOptions = {}): string => {
  const {
    decimals = 1,
    unit = true,
    sign = "auto",
    floorDb = SILENCE_DB,
  } = options;
  const suffix = unit ? " dB" : "";

  // No reading yet. Two hyphens rather than a dash: hosts such as Videorc ban
  // the em dash from user-facing copy.
  if (Number.isNaN(db)) {
    return `--${suffix}`;
  }
  if (db === SILENCE_DB || db <= floorDb) {
    const prefix = sign === "never" ? "" : MINUS_SIGN;
    return `${prefix}${INFINITY_SIGN}${suffix}`;
  }

  const rounded = Number(db.toFixed(decimals));
  const magnitude = Math.abs(rounded).toFixed(decimals);

  if (rounded === 0 || sign === "never") {
    return `${magnitude}${suffix}`;
  }
  if (rounded < 0) {
    return `${MINUS_SIGN}${magnitude}${suffix}`;
  }
  const plus = sign === "auto" ? "+" : "";
  return `${plus}${magnitude}${suffix}`;
};

/** Sample peak of a block of samples, in dBFS. */
export const peakDb = (samples: Iterable<number>): number => {
  let peak = 0;
  for (const sample of samples) {
    const magnitude = Math.abs(sample);
    if (magnitude > peak) {
      peak = magnitude;
    }
  }
  return gainToDb(peak);
};

/** RMS level of a block of samples, in dBFS. */
export const rmsDb = (samples: Iterable<number>): number => {
  let sumOfSquares = 0;
  let count = 0;
  for (const sample of samples) {
    sumOfSquares += sample * sample;
    count += 1;
  }
  if (count === 0) {
    return SILENCE_DB;
  }
  return gainToDb(Math.sqrt(sumOfSquares / count));
};

type FrameListener = (nowMs: number) => void;
type FramePhase = "update" | "paint";

const listeners = {
  paint: new Set<FrameListener>(),
  update: new Set<FrameListener>(),
};
let handle: number | null = null;
let ticking = false;

const hasListeners = () => listeners.update.size + listeners.paint.size > 0;

const reportError = (error: unknown) => {
  queueMicrotask(() => {
    throw error;
  });
};

const tick = (nowMs: number) => {
  handle = null;
  ticking = true;
  for (const phase of [listeners.update, listeners.paint]) {
    for (const listener of phase) {
      try {
        listener(nowMs);
      } catch (error) {
        reportError(error);
      }
    }
  }
  ticking = false;
  if (hasListeners() && handle === null) {
    handle = requestAnimationFrame(tick);
  }
};

/**
 * Runs sources in the update phase, then renderers in the default paint phase.
 * One loop serves the whole page and stops when nothing is subscribed.
 * The browser pauses it while the tab is hidden.
 */
export const subscribeFrame = (
  listener: FrameListener,
  phase: FramePhase = "paint"
): (() => void) => {
  listeners[phase].add(listener);
  if (
    handle === null &&
    !ticking &&
    typeof requestAnimationFrame === "function"
  ) {
    handle = requestAnimationFrame(tick);
  }
  return () => {
    listeners[phase].delete(listener);
    if (!hasListeners() && handle !== null) {
      cancelAnimationFrame(handle);
      handle = null;
    }
  };
};

/** One frame of a task. Return true while the task needs another frame. */
export type FrameTaskStep = (nowMs: number) => boolean;

export interface FrameTask {
  /** Runs the step again from the next frame, if the task is asleep. */
  wake: () => void;
  /** Stops the task for good. A stopped task ignores `wake`. */
  stop: () => void;
}

/**
 * Runs `step` on the shared loop for as long as it returns true. When it
 * returns false the task sleeps and requests no frames until `wake()`, so a
 * settled, silent or hidden painter costs nothing. The task starts awake.
 */
export const createFrameTask = (step: FrameTaskStep): FrameTask => {
  let stopped = false;
  let unsubscribe: (() => void) | null = null;

  const sleep = () => {
    unsubscribe?.();
    unsubscribe = null;
  };

  const run = (nowMs: number) => {
    if (!step(nowMs)) {
      sleep();
    }
  };

  const wake = () => {
    if (!stopped && unsubscribe === null) {
      unsubscribe = subscribeFrame(run);
    }
  };

  wake();

  return {
    stop: () => {
      stopped = true;
      sleep();
    },
    wake,
  };
};

/** The longest step a painter clock takes, so waking never jumps. */
export const MAX_FRAME_GAP_MS = 100;

/**
 * A clock that follows the frames but never advances more than
 * `MAX_FRAME_GAP_MS` at once. A painter that slept, or ran in a hidden tab,
 * resumes its ballistics where they were instead of jumping to the end.
 */
export const createPainterClock = (): ((nowMs: number) => number) => {
  let lastMs: number | null = null;
  let clockMs = 0;
  return (nowMs) => {
    if (lastMs !== null) {
      clockMs += Math.min(Math.max(0, nowMs - lastMs), MAX_FRAME_GAP_MS);
    }
    lastMs = nowMs;
    return clockMs;
  };
};

import type { FrameSource } from "./audio-meters-types";

export interface FrameEmitter<T> extends FrameSource<T> {
  /** Sends a frame to every subscriber. */
  emit: (frame: T) => void;
  /** The last frame emitted, if any. */
  readonly latest: T | undefined;
}

/**
 * Creates a frame source you push to yourself: from a WebSocket, a worker, a
 * native bridge or a test.
 */
export const createFrameEmitter = <T>(): FrameEmitter<T> => {
  const subscribers = new Set<(frame: T) => void>();
  let latest: T | undefined;

  return {
    emit: (frame) => {
      latest = frame;
      for (const subscriber of subscribers) {
        subscriber(frame);
      }
    },
    get latest() {
      return latest;
    },
    subscribe: (listener) => {
      subscribers.add(listener);
      return () => {
        subscribers.delete(listener);
      };
    },
  };
};

export interface FrameRelay<T> extends FrameSource<T> {
  /** Forwards frames from `source`. Subscribers stay attached when it changes. */
  setSource: (source: FrameSource<T> | null) => void;
}

/**
 * A frame source whose upstream can be swapped. Components keep a stable
 * subscription while the audio behind it is rebuilt.
 */
export const createFrameRelay = <T>(): FrameRelay<T> => {
  const subscribers = new Set<(frame: T) => void>();
  let source: FrameSource<T> | null = null;
  let detach: (() => void) | null = null;

  const forward = (frame: T) => {
    for (const subscriber of subscribers) {
      subscriber(frame);
    }
  };

  const attach = () => {
    if (!detach && source && subscribers.size > 0) {
      detach = source.subscribe(forward);
    }
  };

  const release = () => {
    detach?.();
    detach = null;
  };

  return {
    setSource: (next) => {
      if (next === source) {
        return;
      }
      release();
      source = next;
      attach();
    },
    subscribe: (listener) => {
      subscribers.add(listener);
      attach();
      return () => {
        subscribers.delete(listener);
        if (subscribers.size === 0) {
          release();
        }
      };
    },
  };
};

import { clamp, DEFAULT_MIN_DB } from "./audio-meters-decibels";
import type { Taper } from "./audio-meters-types";

const DEFAULT_FADER_MAX_DB = 6;
const DEFAULT_UNITY_POSITION = 0.75;
const AUDIO_CURVE_EXPONENT = 2;

/** Equal distance per unit across the range. */
export const linearTaper = (min: number, max: number): Taper => ({
  toPosition: (value) => {
    if (!(value > min)) {
      return 0;
    }
    return clamp((value - min) / (max - min), 0, 1);
  },
  toValue: (position) => min + clamp(position, 0, 1) * (max - min),
});

export interface AudioTaperOptions {
  minDb?: number;
  maxDb?: number;
  /** Where 0 dB sits on the travel, 0..1. Default 0.75. */
  unityPosition?: number;
}

/**
 * A console-style fader law: more travel around 0 dB, a fast fall to the
 * bottom of the range, and linear headroom above 0 dB.
 */
export const audioTaper = ({
  minDb = DEFAULT_MIN_DB,
  maxDb = DEFAULT_FADER_MAX_DB,
  unityPosition = DEFAULT_UNITY_POSITION,
}: AudioTaperOptions = {}): Taper => {
  const anchorDb = Math.min(0, maxDb);
  const unity = maxDb > 0 ? clamp(unityPosition, 0, 1) : 1;

  const toPosition = (db: number): number => {
    if (!(db > minDb)) {
      return 0;
    }
    if (db >= maxDb) {
      return 1;
    }
    if (db >= anchorDb) {
      return unity + ((db - anchorDb) / (maxDb - anchorDb)) * (1 - unity);
    }
    const ratio = (db - anchorDb) / (minDb - anchorDb);
    const travel = 1 - ratio ** (1 / AUDIO_CURVE_EXPONENT);
    return travel * unity;
  };

  const toValue = (position: number): number => {
    const clamped = clamp(position, 0, 1);
    if (clamped >= unity) {
      if (unity >= 1) {
        return anchorDb;
      }
      return anchorDb + ((clamped - unity) / (1 - unity)) * (maxDb - anchorDb);
    }
    const travel = unity > 0 ? clamped / unity : 0;
    return anchorDb + (minDb - anchorDb) * (1 - travel) ** AUDIO_CURVE_EXPONENT;
  };

  return { toPosition, toValue };
};

/** Logarithmic law for frequency and time parameters. `min` must be above 0. */
export const logTaper = (min: number, max: number): Taper => {
  const span = Math.log(max / min);
  return {
    toPosition: (value) => {
      if (!(value > min)) {
        return 0;
      }
      return clamp(Math.log(value / min) / span, 0, 1);
    },
    toValue: (position) => min * Math.exp(clamp(position, 0, 1) * span),
  };
};

export type TaperInput = "linear" | "audio" | "log" | Taper;

/** Resolves a taper name or object for a range. */
export const resolveTaper = (
  taper: TaperInput,
  min: number,
  max: number
): Taper => {
  if (typeof taper !== "string") {
    return taper;
  }
  if (taper === "audio") {
    return audioTaper({ maxDb: max, minDb: min });
  }
  if (taper === "log") {
    return logTaper(min, max);
  }
  return linearTaper(min, max);
};

/** A level reading for one audio channel, in dBFS. */
export interface ChannelLevel {
  /** Sample peak in dBFS. `-Infinity` is digital silence. */
  peakDb: number;
  /** RMS level in dBFS, when the source measures it. */
  rmsDb?: number;
}

/** One metering update: one entry per channel (1 = mono, 2 = stereo). */
export interface MeterFrame {
  channels: ChannelLevel[];
}

/** One visualisation update from an analyser. */
export interface VisualFrame {
  /** Frequency bands, 0..1 each, low to high. */
  bands: Float32Array;
  /** Ring buffer of recent broadband levels, 0..1 each. */
  history: Float32Array;
  /** Index of the oldest entry in `history`. */
  historyStart: number;
  /** Number of valid entries in `history`. */
  historyLength: number;
  /** Time of the newest history entry, in the requestAnimationFrame clock. */
  historyUpdatedAt?: number;
  /** Minimum time between entries, used for playback delay. 0 disables smoothing. */
  historyIntervalMs?: number;
  /** Last entry removed from a full history ring, for its scrolling edge. */
  historyPreviousLevel?: number;
  /** Raw time-domain samples, −1..1, for line and scope drawing. */
  timeDomain?: Float32Array;
  /** Sample peak of this frame in dBFS. */
  peakDb: number;
}

/** Anything that can push frames to subscribers. */
export interface FrameSource<T> {
  subscribe: (listener: (frame: T) => void) => () => void;
}

export type MeterZoneName = "ok" | "warn" | "clip";

/** A colour zone of a meter, starting at `fromDb` and running to the next zone. */
export interface MeterZone {
  fromDb: number;
  zone: MeterZoneName;
}

/** Maps a value (usually dB) to a 0..1 position on a control, and back. */
export interface Taper {
  toPosition: (value: number) => number;
  toValue: (position: number) => number;
}

export type Orientation = "horizontal" | "vertical";

"use client";

import { createContext, useContext, useMemo } from "react";
import type { ReactNode } from "react";

import type { BallisticsInput } from "./audio-meters-ballistics";
import type { MeterZone, Orientation } from "./audio-meters-types";

export type AudioSize = "sm" | "default" | "lg";

/**
 * Settings a container (a mixer or channel strip) passes down to the audiocn
 * components inside it. Explicit props on a component always win.
 */
export interface AudioConfig {
  orientation?: Orientation;
  size?: AudioSize;
  disabled?: boolean;
  /** Muted or silenced by another channel's solo: meters render dimmed. */
  dimmed?: boolean;
  minDb?: number;
  maxDb?: number;
  zones?: MeterZone[];
  ballistics?: BallisticsInput;
}

const AudioConfigContext = createContext<AudioConfig>({});

export interface AudioConfigProviderProps {
  value: AudioConfig;
  children: ReactNode;
}

/** Merges `value` over any config from a parent provider. */
export const AudioConfigProvider = ({
  value,
  children,
}: AudioConfigProviderProps) => {
  const parent = useContext(AudioConfigContext);
  const {
    ballistics,
    dimmed,
    disabled,
    maxDb,
    minDb,
    orientation,
    size,
    zones,
  } = value;

  const merged = useMemo<AudioConfig>(
    () => ({
      ballistics: ballistics ?? parent.ballistics,
      dimmed: (dimmed ?? false) || (parent.dimmed ?? false),
      disabled: (disabled ?? false) || (parent.disabled ?? false),
      maxDb: maxDb ?? parent.maxDb,
      minDb: minDb ?? parent.minDb,
      orientation: orientation ?? parent.orientation,
      size: size ?? parent.size,
      zones: zones ?? parent.zones,
    }),
    [
      ballistics,
      dimmed,
      disabled,
      maxDb,
      minDb,
      orientation,
      parent,
      size,
      zones,
    ]
  );

  return (
    <AudioConfigContext.Provider value={merged}>
      {children}
    </AudioConfigContext.Provider>
  );
};

/** The config from the nearest mixer or channel strip, or `{}`. */
export const useAudioConfig = (): AudioConfig => useContext(AudioConfigContext);

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import { CLIP_HOLD_MS, CLIP_THRESHOLD_DB } from "./audio-meters-zones";

export interface UseClipHoldOptions {
  /** Levels at or above this count as a clip. Default −1 dBFS. */
  thresholdDb?: number;
  /** How long the clip state holds. `Infinity` latches until `reset()`. Default 1500 ms. */
  holdMs?: number;
  onClippingChange?: (clipping: boolean) => void;
}

export interface ClipHold {
  clipping: boolean;
  /** Number of separate clips since mount or the last reset. */
  count: number;
  /** Feed every level reading here. */
  report: (db: number) => void;
  reset: () => void;
}

export const useClipHold = ({
  thresholdDb = CLIP_THRESHOLD_DB,
  holdMs = CLIP_HOLD_MS,
  onClippingChange,
}: UseClipHoldOptions = {}): ClipHold => {
  const [clipping, setClipping] = useState(false);
  const [count, setCount] = useState(0);
  const clippingRef = useRef(false);
  const aboveRef = useRef(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const onChangeRef = useRef(onClippingChange);

  useEffect(() => {
    onChangeRef.current = onClippingChange;
  });

  const update = useCallback((next: boolean) => {
    if (clippingRef.current === next) {
      return;
    }
    clippingRef.current = next;
    setClipping(next);
    onChangeRef.current?.(next);
  }, []);

  const clearTimer = useCallback(() => {
    if (timerRef.current !== null) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
  }, []);

  const scheduleRelease = useCallback(() => {
    clearTimer();
    if (Number.isFinite(holdMs)) {
      timerRef.current = setTimeout(() => {
        timerRef.current = null;
        update(false);
      }, holdMs);
    }
  }, [clearTimer, holdMs, update]);

  const report = useCallback(
    (db: number) => {
      const above = db >= thresholdDb;
      const wasAbove = aboveRef.current;
      aboveRef.current = above;
      if (!above) {
        return;
      }
      if (!wasAbove) {
        setCount((previous) => previous + 1);
      }
      update(true);
      scheduleRelease();
    },
    [scheduleRelease, thresholdDb, update]
  );

  const reset = useCallback(() => {
    clearTimer();
    aboveRef.current = false;
    setCount(0);
    update(false);
  }, [clearTimer, update]);

  useEffect(() => {
    // An Activity hide cancels a pending release; re-arm it on show so the
    // light doesn't stay on.
    if (clippingRef.current && timerRef.current === null) {
      scheduleRelease();
    }
    return clearTimer;
  }, [clearTimer, scheduleRelease]);

  return { clipping, count, report, reset };
};

"use client";

import { useEffect } from "react";
import { useEffectEvent } from "./audio-meters-use-effect-event";

import type { FrameSource } from "./audio-meters-types";

export interface UseFrameSourceOptions {
  /** Pause the subscription without unmounting. Default true. */
  enabled?: boolean;
}

/**
 * Subscribes `onFrame` to a frame source. The callback can change on every
 * render without resubscribing.
 */
export const useFrameSource = <T>(
  source: FrameSource<T> | null | undefined,
  onFrame: (frame: T) => void,
  { enabled = true }: UseFrameSourceOptions = {}
): void => {
  const handleFrame = useEffectEvent(onFrame);

  useEffect(() => {
    if (!(source && enabled)) {
      return;
    }
    return source.subscribe((frame) => {
      handleFrame(frame);
    });
  }, [source, enabled]);
};

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

const subscribe = (onChange: () => void) => {
  if (typeof window === "undefined" || !window.matchMedia) {
    return () => {
      // Nothing to unsubscribe on the server.
    };
  }
  const media = window.matchMedia(QUERY);
  media.addEventListener("change", onChange);
  return () => {
    media.removeEventListener("change", onChange);
  };
};

const getSnapshot = () =>
  typeof window !== "undefined" && Boolean(window.matchMedia?.(QUERY).matches);

const getServerSnapshot = () => false;

/** True when the user asked the system to reduce motion. */
export const useReducedMotion = (): boolean =>
  useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);

"use client";

import { useEffect, useRef } from "react";
import { useEffectEvent } from "./audio-meters-use-effect-event";
import type { RefObject } from "react";

/**
 * Tracks whether an element is on screen, in a ref, so a painter can skip
 * frames nobody can see. Reading it never re-renders. `onChange` runs when the
 * element comes into or leaves view, so a painter that slept while hidden can
 * wake up.
 */
export const useVisibility = (
  target: RefObject<Element | null>,
  onChange?: (visible: boolean) => void
): RefObject<boolean> => {
  const visibleRef = useRef(true);
  const handleChange = useEffectEvent((visible: boolean) => {
    onChange?.(visible);
  });
  useEffect(() => {
    const element = target.current;
    if (!element || typeof IntersectionObserver === "undefined") {
      return;
    }
    const observer = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting !== visibleRef.current) {
          visibleRef.current = entry.isIntersecting;
          handleChange(entry.isIntersecting);
        }
      }
    });
    observer.observe(element);
    return () => {
      observer.disconnect();
    };
  }, [target]);
  return visibleRef;
};

import type { MeterZone, MeterZoneName } from "./audio-meters-types";

/** Green below −20 dBFS, amber from −20, red from −9: the thresholds streamers know. */
export const DEFAULT_ZONES: MeterZone[] = [
  { fromDb: Number.NEGATIVE_INFINITY, zone: "ok" },
  { fromDb: -20, zone: "warn" },
  { fromDb: -9, zone: "clip" },
];

/** A level at or above this counts as clipping for a clip light. */
export const CLIP_THRESHOLD_DB = -1;
/** How long a clip light stays on after the last clip. */
export const CLIP_HOLD_MS = 1500;

/** The zone a level falls in. */
export const zoneForDb = (
  db: number,
  zones: MeterZone[] = DEFAULT_ZONES
): MeterZoneName => {
  let current: MeterZoneName = "ok";
  for (const zone of zones) {
    if (db >= zone.fromDb) {
      current = zone.zone;
    }
  }
  return current;
};

import { useCallback, useInsertionEffect, useRef } from "react";

// Stand-in for React's `useEffectEvent`: Next 15's bundled React does not
// export it yet. Returns a stable function that always calls the latest `fn`.
export function useEffectEvent<A extends unknown[], R>(fn: (...args: A) => R): (...args: A) => R {
  const ref = useRef(fn);
  useInsertionEffect(() => {
    ref.current = fn;
  });
  return useCallback((...args: A) => ref.current(...args), []);
}
